import {slotBannerSize,sizeLabel} from '../mock-app/banner-sizes.js';
import {bannerFrames,frameOf,framePlacement} from '../mock-app/carousel-model.js';
import {carouselForm,readCarouselForm} from './carousel-editor.js';
import {deepLinkUrl,resolveBannerLink} from '../mock-app/deep-links.js';
import {deepLinkField} from './deep-link-editor.js';
import {menuCategories,menuCategoryOf,menuContentOptions} from '../mock-app/menu-model.js';
import {challengeOrder,moveChallenge,isFixedMission,saveMissionConfig} from './model.js';
import {uploadField,offerPicker,initBannerEditor} from './banner-editor.js';
// タメルコ 管理画面モック（mock-admin）
// アプリモック（mock-app）と同じ localStorage の状態を読み書きする。管理画面の変更はアプリ側に即時反映される。
// 各画面に「spec」（poikatsu-spec admin/ に既存の運用機能）／「新規」（現行仕様にない運用機能）／「外部再現」（NACS 等の外部イベントの再現）を表示する。
import {KEY,TODAY,yen,pt,offersOf,surveys,initialState,day,L,applyReservations,visibleSlots,challengeSlots,challengeAchieved,total,autoReview,manualReview,reviewPending,exchangeConditions,validateSlot,publishSlot,removeSlot,POINT_KEYS,reservePointSetting,deleteReservation,setMissionReward,setMissionEnabled,setSurveyRate,setExchangeCap,activeScreenSetting,saveScreenSetting,deleteScreenSetting,progressOffer,rejectOffer,audit,surveyReward,missionTasks,featurePublication,saveFeature,removeFeature,slotLink,CHINCHIRO_ROLES,ensureChinchiro,chinchiroStatus,setChinchiro} from './model.js';
const root=document.querySelector('#root'),modal=document.querySelector('#modal');
let state;function load(){try{const s=JSON.parse(localStorage.getItem(KEY));state=s&&s.version===9?s:initialState();}catch{state=initialState();}applyReservations(state);}
load();
let slotFilter='all',screenCode='tametoku_quick',editingSlot=null,editingSetting=null,editingFeature=null,editingCampaignBanner=null,formError='',toastTimer;
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=()=>({slots:'banners',features:'campaigns','text-ads':'banners'})[location.hash.slice(1)]||location.hash.slice(1).split('/')[0]||'dashboard';
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const toast=t=>{const el=document.querySelector('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);};
const badge=(kind,text)=>`<span class="badge ${kind}">${text||({spec:'spec',new:'新規',ext:'外部再現'})[kind]}</span>`;
const kindName={banner:'バナー（最上部）',ad:'カテゴリ広告（架空サービス）',campaign:'キャンペーン（ブースト）',recommend:'おすすめ',challenge:'チャレンジボーナス',ticker:'テキストバナー',notice:'告知'};
const tabName={daily:'ホーム：デイリーミッション',steps:'ホーム：歩数',challenge:'ホーム：チャレンジボーナス',game:'ホーム：ゲーム',shopping:'ホーム：買い物',survey:'ホーム：アンケート',chat:'ホーム：チャット',credit:'ホーム：クレカ',high:'お得：ガポガポ',quick:'お得：すぐできる'};
const placementName={'daily-middle':'ホーム枠 → デイリーミッション中部（320×50）',top:'ホーム最上部バナー（home_first）',category:'カテゴリ広告枠（ホーム各タブ／お得：ガポガポ・すぐできる）',carousel:'ホーム特集枠',feed:'おすすめ枠',popup:'起動時ポップアップ',pill:'お得 テキストバナー',challenge:'チャレンジ枠',sub:'サブ枠'};
const segmentName={all:'全員',new:'新規',regular:'継続',finance:'金融未利用'};
const destName=id=>offersOf(state).find(o=>o.id===id)?.name||({survey:'アンケート',wallet:'ポイント・交換'})[id]||id;
const slotStatus=s=>!s.enabled?['off','停止中']:s.start>state.date?['warn','予約中']:s.end<state.date?['off','期間終了']:['on','配信中'];

// ===== 共通 =====
function shell(title,content){const items=[['dashboard','ダッシュボード',''],['sec','運用'],['top-menu','TOP画面上部のメニュー',''],['missions','デイリーミッション設定',''],['challenges','チャレンジボーナス',''],['banners','バナー&テキスト広告',''],['campaigns','キャンペーンページ',''],['sec','報酬・判定'],['chinchiro','チンチロ（日次抽選）','new'],['points','付与設定（歩数・動画）','spec'],['survey','アンケート還元率','spec'],['review','審査・交換上限','spec'],['sec','確認'],['screens','案件グループ設定','spec'],['cases','成果・解禁（NACS 再現）','ext'],['metrics','実績','new'],['logs','変更ログ','']];const r=route();
 return `<div class="layout"><aside class="side"><div class="brand"><i>P</i>タメルコ 管理画面</div><nav>${items.map(([k,l,b])=>k==='sec'?`<div class="sec">${l}</div>`:`<a href="#${k}" class="${r===k?'current':''}">${l}${b?badge(b):''}</a>`).join('')}</nav><div class="foot">凡例：${badge('spec')} poikatsu-spec の admin/ に既存<br>${badge('new')} 現行仕様にない新規機能<br>${badge('ext')} 外部連携（NACS）の再現<br><br><a href="../mock-app/" target="_blank">アプリモックを開く ↗</a><br><a href="../mock-nacs/" target="_blank">NACS モックを開く ↗</a><br>同じブラウザーなら変更が即時反映されます。</div></aside><div><header class="topbar"><h1>${title}</h1><span class="meta">運用者：デモ運用者（管理者ロール）</span><label>確認日 <input type="date" id="admin-date" value="${state.date}"></label><button class="btn sm" data-action="reload">アプリの状態を再読み込み</button></header><main>${content}</main></div></div>`;}

// ===== ダッシュボード =====
function dashboard(){const pend=state.user.pendings;const act=visibleSlots(state);const t=missionTasks(state);const chin=(()=>{try{ensureChinchiro(state);return chinchiroStatus(state);}catch{return null;}})();return `<div class="cards">
<div class="card"><h3>アプリ構成（現行モック）</h3><b>下部 4 タブ</b><p class="tiny">ホーム ・ お得 ・ 簡単 ・ マイページ</p><p class="tiny" style="margin-top:6px"><b>お得</b>のサブタブ：おすすめ／ガポガポ／すぐできる／マイ案件<br><b>簡単</b>＝アンケート主軸<br><b>マイページ</b>＝マイ案件・友達招待・交換</p></div>
<div class="card"><h3>目減りゼロ表示</h3><b>${state.showNoLoss!==false?'ON':'OFF'}</b><p class="tiny">ホーム残高・マイページの比較表示</p><p style="margin-top:8px"><button class="btn sm" data-action="toggle-noloss">${state.showNoLoss!==false?'表示をOFF':'表示をON'}</button></p></div>
<div class="card"><h3>チンチロ</h3><b>${chin&&chin.visible?`残り ${chin.remaining}/${chin.dailyLimit}`:'停止／非表示'}</b><p class="tiny">3つ一致：大当たり ／ 2つ一致：当たり</p><p class="tiny" style="margin-top:6px"><a href="#chinchiro">チンチロ設定へ</a></p></div>
<div class="card"><div class="k">配信中の運用枠</div><div class="v">${act.length}<small>/ ${state.slots.length}</small></div><div class="s">${act.filter(x=>x.kind==='challenge').length}件のチャレンジ開催中</div></div>
<div class="card"><div class="k">審査待ち（付与予定）</div><div class="v">${pend.length}<small>件</small></div><div class="s">自動判定 ${pend.filter(x=>x.review==='auto').length}／有人審査 ${pend.filter(x=>x.review==='manual').length}</div></div>
<div class="card"><div class="k">デモ利用者の合算ポイント</div><div class="v">${pt(total(state))}<small>pt</small></div><div class="s">交換可能 ${pt(state.user.approved)}／準備中 ${pt(state.user.pending)}</div></div>
<div class="card"><div class="k">本日のミッション進捗</div><div class="v">${t.done}<small>/ ${t.total}</small></div><div class="s">受け取り可能 ${t.claimable}件</div></div>
<div class="card"><div class="k">日次交換総額</div><div class="v">${Math.round(state.exchangeUsedToday/L(state).exchangeDailyCap*100)}<small>%</small></div><div class="s">${pt(state.exchangeUsedToday)} / ${pt(L(state).exchangeDailyCap)} pt</div></div>
</div>
<div class="two"><section class="panel"><h2>本日の配信内容</h2><div class="tbl"><table><thead><tr><th>枠</th><th>種別</th><th>表示位置</th><th>期間</th></tr></thead><tbody>${act.map(s=>`<tr><td><a href="#${s.kind==='challenge'?'challenges':s.placements.includes('pill')?'banners/offers/text':'banners'}">${esc(s.name)}</a></td><td>${kindName[s.kind]}</td><td>${s.placements.map(p=>placementName[p]||p).join('・')}</td><td>${s.start.slice(5)}〜${s.end.slice(5)}</td></tr>`).join('')||'<tr><td colspan="4" class="tiny">配信中の枠はありません</td></tr>'}</tbody></table></div></section>
<section class="panel"><h2>最近の変更</h2><div class="tbl"><table><thead><tr><th>日時</th><th>操作</th></tr></thead><tbody>${state.logs.slice(0,8).map(l=>`<tr><td class="tiny">${l.at.slice(0,16).replace('T',' ')}</td><td>${esc(l.label)}</td></tr>`).join('')||'<tr><td colspan="2" class="tiny">変更はまだありません</td></tr>'}</tbody></table></div><p class="tiny" style="margin-top:8px"><a href="#logs">変更ログをすべて見る</a></p></section></div>
<section class="panel"><h2>このモックの位置づけ</h2><p class="desc">ユーザー向けアプリのモック（mock-app）を実現するための運用画面。アプリは下部 4 タブ（ホーム／お得／簡単／マイページ）。お得内はおすすめ／ガポガポ／すぐできる／マイ案件。チンチロ・目減りゼロはダッシュボードと各設定画面から操作。既存の運用機能（poikatsu-spec の admin/）と新規運用機能を同じ画面群で扱う。案件そのもの（登録・報酬・掲出順・成果の承認）は <a href="../mock-nacs/" target="_blank">NACS モック</a> が持ち、この管理画面は「どの画面にどのグループを出すか」と「成果をポイントに換える」側だけを扱う。既存機能との差分は次段階のドキュメントで整理する。</p></section>`;}

// ===== 運用枠 =====
const slotSection=()=>route()==='challenges'?'challenge':['#text-ads','#banners/offers/text'].includes(location.hash)?'text':'banner';
const slotPageTitle=()=>({challenge:'チャレンジボーナス',text:'オトク内テキスト広告',banner:'バナー&テキスト広告'})[slotSection()];
const belongsToSection=(s,section)=>section==='challenge'?s.kind==='challenge':section==='text'?s.kind==='ticker'||s.placements.includes('pill'):s.kind!=='ticker'&&!s.placements.includes('pill')&&(s.kind!=='challenge'||s.placements.some(p=>p!=='challenge'));
function slotForm(v){if(slotSection()==='banner')return carouselForm(state,v,location.hash.slice(1).split('/').slice(1));const section=slotSection(),o=v||{id:'slot-'+crypto.randomUUID().slice(0,8),name:'',kind:section==='challenge'?'challenge':section==='text'?'ticker':'banner',destination:'travel',placements:section==='challenge'?['challenge']:section==='text'?['pill']:['top'],enabled:true,start:state.date,end:state.date.slice(0,8)+'30',segment:'all',priority:50,title:'',text:'',rewardMode:'flat',reward:0,to:'',challengeGoal:1000,participants:0,bonus:100};
const input=(label,name,value,type='text')=>`<label>${label}<input type="${type}" name="${name}" value="${esc(value??'')}" required></label>`;
return `<form class="grid" id="slot-form" data-id="${o.id}" data-section="${section}">${input('管理名（必須）','name',o.name)}<input type="hidden" name="kind" value="${o.kind}">${section==='banner'?`<label class="wide">リンク先の案件・特集ページ（URL）<input name="to" value="${esc(deepLinkUrl(o.to||'offer/'+o.destination,location.href))}" placeholder="コピーしたディープリンクを貼り付け" required></label>`:`<label>リンク先の案件<select name="destination">${offersOf(state).map(x=>`<option value="${x.id}" ${x.id===o.destination?'selected':''}>${esc(x.name)}</option>`).join('')}${['survey','wallet'].includes(o.destination)?`<option value="${o.destination}" selected>${destName(o.destination)}</option>`:''}</select></label>`}${input('表示開始日','start',o.start,'date')}${input('表示終了日','end',o.end,'date')}${input('優先度（0〜100）','priority',o.priority,'number')}<label>公開状態<select name="enabled"><option value="1" ${o.enabled?'selected':''}>公開</option><option value="0" ${!o.enabled?'selected':''}>停止</option></select></label><label>対象者<select name="segment">${Object.entries(segmentName).map(([k,n])=>`<option value="${k}" ${o.segment===k?'selected':''}>${n}</option>`).join('')}</select></label>
${section==='banner'?`${o.placements.includes('challenge')?'<input type="hidden" name="placements" value="challenge">':''}<div class="wide"><h3>配信先</h3><div class="checks">${Object.entries(placementName).filter(([k])=>!['pill','challenge'].includes(k)).map(([k,n])=>`<label><input type="checkbox" name="placements" value="${k}" ${o.placements.includes(k)?'checked':''}>${n}</label>`).join('')}</div></div><label>カテゴリ広告のタブ<select name="tab"><option value="">指定なし</option>${Object.entries(tabName).map(([k,n])=>`<option value="${k}" ${o.tab===k?'selected':''}>${n}</option>`).join('')}</select></label><label>カテゴリ広告の位置<select name="position"><option value="top" ${o.position!=='bottom'?'selected':''}>上部</option><option value="bottom" ${o.position==='bottom'?'selected':''}>下部</option></select></label>${uploadField(o)}`:o.placements.map(p=>`<input type="hidden" name="placements" value="${p}">`).join('')}
${section==='text'?`<label class="wide">広告テキスト<textarea name="title" maxlength="120" required>${esc(o.title)}</textarea></label><p class="tiny wide">オトクの検索窓の下に表示するテキスト広告です。</p>`:''}
${section==='challenge'?`${input('目標人数','challengeGoal',o.challengeGoal,'number')}${input('現在の参加人数（デモ）','participants',o.participants,'number')}${input('達成ボーナス（pt）','bonus',o.bonus,'number')}`:section==='banner'?'':`<label class="wide">タップ先（案件またはキャンペーンページ）<input name="to" value="${esc(o.to||'offer/'+o.destination)}" list="deeplinks" required><datalist id="deeplinks">${(state.features||[]).map(f=>`<option value="feature/${f.id}">${esc(f.title)}</option>`).join('')}${offersOf(state).map(x=>`<option value="offer/${x.id}">${esc(x.name)}</option>`).join('')}</datalist></label>`}
<div class="actions"><button class="btn primary" type="submit">${v?'更新して反映':'追加して反映'}</button><button class="btn" type="button" data-action="cancel-slot">閉じる</button><span class="err" role="alert">${esc(formError)}</span></div></form>`;}
function campaignBanners(){return `<section class="panel"><h2>キャンペーンページ内のバナー</h2><p class="desc">ページ上部の画像もここでまとめて差し替えます。掲載案件は「キャンペーンページ」で編集します。</p>${editingCampaignBanner?(()=>{const f=state.features.find(x=>x.id===editingCampaignBanner);return f?`<form id="campaign-banner-form" class="grid" data-id="${f.id}"><h3 class="wide">${esc(f.title)}</h3>${uploadField(f)}<div class="actions"><button class="btn primary">画像を保存</button><button type="button" class="btn" data-action="close-campaign-banner">閉じる</button><span class="err" role="alert"></span></div></form>`:'';})():''}<div class="tbl"><table><thead><tr><th>キャンペーン</th><th>画像</th><th>操作</th></tr></thead><tbody>${(state.features||[]).map(f=>`<tr><td>${esc(f.title)}</td><td>${f.bannerImage?'登録済み':'未登録'}</td><td><button class="btn" data-action="edit-campaign-banner" data-id="${f.id}">バナーを編集</button> <a href="../mock-app/#feature/${f.id}" target="_blank">アプリで確認</a></td></tr>`).join('')}</tbody></table></div></section>`;}
function challengeOrderPage(){const list=challengeOrder(state);return `<section class="panel"><h2>チャレンジボーナスの並び順</h2><p class="desc">上にある案件からアプリに表示します。案件詳細・開催期間・目標人数・ボーナスはNACSで編集します。</p><p><a href="../mock-nacs/#challenges" target="_blank">NACSでチャレンジボーナスを編集 ↗</a></p><table><thead><tr><th>表示順</th><th>案件</th><th>期間</th><th>ボーナス</th><th>並び替え</th></tr></thead><tbody>${list.map((c,i)=>`<tr><td>${i+1}</td><td>${esc(destName(c.destination))}</td><td>${esc(c.start)}〜${esc(c.end)}</td><td>${pt(c.bonus)}pt</td><td><button class="btn" data-action="move-challenge" data-id="${c.id}" data-dir="-1" ${i===0?'disabled':''}>上へ</button> <button class="btn" data-action="move-challenge" data-id="${c.id}" data-dir="1" ${i===list.length-1?'disabled':''}>下へ</button></td></tr>`).join('')}</tbody></table></section>`;}
const frameTitle=(frame,position)=>position==='top'?'デイリーミッション · 上部':bannerFrames[frame].positions[position].replace(/・?320×\d+|・?300×\d+|（320×100）/g,'').replace(/[（）]/g,'').replace(/・$/,'').replace('広告枠','広告');
function bannerFramesPage(){return `<div class="banner-workspace"><div class="banner-heading"><div><h2>配信枠を選択</h2><p>バナーを掲載する場所ごとに、登録・編集できます。</p></div><span class="banner-note">配信対象がない枠は自動で非表示</span></div>${Object.entries(bannerFrames).map(([frame,group])=>`<section class="banner-group"><h3>${group.label}</h3><div class="banner-frame-grid">${Object.entries(group.positions).map(([position])=>{const slots=state.slots.filter(s=>{const [f,p]=frameOf(s);return f===frame&&p===position;});return `<a class="banner-frame-card" href="#banners/${frame}/${position}"><span class="banner-frame-top"><span class="banner-size-chip">${sizeLabel(slotBannerSize(framePlacement(frame,position)))}</span><span aria-hidden="true">↗</span></span><strong>${esc(frameTitle(frame,position))}</strong><span class="banner-frame-bottom"><span>${slots.length}件の登録</span><span>管理する →</span></span></a>`;}).join('')}${frame==='offers'?`<a class="banner-frame-card" href="#banners/offers/text"><span class="banner-frame-top"><span class="banner-size-chip">テキスト</span><span aria-hidden="true">↗</span></span><strong>オトク · 検索窓下</strong><span class="banner-frame-bottom"><span>${state.slots.filter(s=>belongsToSection(s,'text')).length}件の登録</span><span>管理する →</span></span></a>`:''}</div></section>`).join('')}<section class="banner-group"><h3>キャンペーンページ枠</h3><a class="banner-feature-link" href="#banners/features"><strong>特集ページ · 上部</strong><span class="banner-size-chip">320×100px</span><span>画像を管理 →</span></a></section></div>`;}
function bannerFramePage(frame,position){const text=position==='text';const list=state.slots.filter(s=>text?belongsToSection(s,'text'):belongsToSection(s,'banner')&&frameOf(s)[0]===frame&&frameOf(s)[1]===position);return `<div class="banner-workspace"><nav class="banner-breadcrumb"><a href="#banners">バナー&テキスト広告</a><span>／</span><span>${esc(bannerFrames[frame].label)}</span></nav><div class="banner-heading"><div><h2>${text?'オトク · 検索窓下':esc(frameTitle(frame,position))}</h2><p>${text?'検索窓の下に表示する広告文とリンク先を設定します。':position==='popup'?'300×250pxのバナーを1回につき1枚表示します。配信候補が複数ある場合は均等に1枚を選びます。':'複数のバナーは均等にカルーセル表示されます。'}</p></div><span class="banner-size-chip">${text?'テキスト':sizeLabel(slotBannerSize(framePlacement(frame,position)))}</span></div>${editingSlot!==null?`<section class="panel banner-edit-panel"><h3>${text?(editingSlot?'テキスト広告を編集':'テキスト広告を新規登録'):(editingSlot?'バナー設定を編集':'バナーを新規登録')}</h3>${slotForm(editingSlot||null)}</section>`:`<section class="panel banner-list-panel"><div class="banner-list-heading"><h3>${text?'登録済みテキスト広告':'登録済みバナー'} <span class="tiny">${list.length}件</span></h3><button class="btn primary" data-action="new-slot">＋ 新規登録</button></div>${list.length?`<div class="banner-records">${list.map(s=>{const [k,n]=slotStatus(s);return `<article class="banner-record"><div class="banner-record-main"><strong>${esc(s.name)}</strong><div class="banner-record-meta">${badge(k,n)}<span>${text?'テキスト':position==='popup'?'1枚':(s.slides?.length||1)+'枚'}</span><span>${esc(s.start)} 〜 ${esc(s.end)}</span></div></div><div class="banner-record-actions"><button class="btn primary" data-action="edit-slot" data-id="${s.id}">編集</button><button class="btn" data-action="toggle-slot" data-id="${s.id}">${s.enabled?'停止':'再開'}</button><details class="banner-more"><summary class="btn" aria-label="その他の操作">⋯</summary><div><button class="btn" data-action="dup-slot" data-id="${s.id}">複製</button><button class="btn danger" data-action="del-slot" data-id="${s.id}">削除</button></div></details></div></article>`;}).join('')}</div>`:'<div class="banner-empty"><strong>まだバナーが登録されていません</strong><p>「新規登録」から広告を設定してください。</p><small>登録・公開するまで、この枠はアプリに表示されません。</small></div>'}</section>`}</div>`;}
function slotsPage(){if(route()==='challenges')return challengeOrderPage();const section=slotSection(),[frame,position]=location.hash.slice(1).split('/').slice(1);if(section==='text')return bannerFramePage('offers','text');if(section==='banner'&&frame==='features')return `<a href="#banners">← バナー&テキスト広告の枠一覧</a>${campaignBanners()}`;if(section==='banner'&&!bannerFrames[frame]?.positions[position])return bannerFramesPage();if(section==='banner')return bannerFramePage(frame,position);const list=state.slots.filter(s=>belongsToSection(s,section)&&(section!=='banner'||(()=>{const [f,p]=frameOf(s);return f===frame&&p===position;})()));return `${section==='banner'?'<a href="#banners">← バナー&テキスト広告の枠一覧</a>':''}<section class="panel"><h2>${section==='banner'?esc(bannerFrames[frame].positions[position])+'枠':slotPageTitle()}</h2><p class="desc">${section==='banner'?'この枠に表示するバナーを登録・編集します。複数のバナーは自動でカルーセル表示されます。全件停止すると枠ごと非表示になります。':'オトクの検索窓の下にある広告枠です。広告テキスト・タップ先・掲載期間を管理します。'}</p><div class="toolbar"><span class="grow"></span><button class="btn primary" data-action="new-slot">＋ 新規作成</button></div>
${editingSlot!==null?`<div class="panel" style="background:#FAFCFB">${slotForm(editingSlot||null)}</div>`:''}
<div class="tbl"><table><thead><tr><th>管理名</th><th>種別</th><th>表示位置</th><th>リンク先</th><th>期間</th>${section==='banner'?'<th>バナー枚数</th>':'<th>対象</th><th>優先度</th>'}<th>報酬</th><th>状態</th><th>操作</th></tr></thead><tbody>${list.map(s=>{const [k,n]=slotStatus(s);return `<tr class="${k==='off'?'dim':''}"><td><b>${esc(s.name)}</b><div class="tiny">${esc(s.title).split('\n')[0]}</div></td><td>${kindName[s.kind]||s.kind}</td><td>${section==='banner'?(()=>{const [frame,position]=frameOf(s);return frame?`${bannerFrames[frame].label} → ${bannerFrames[frame].positions[position]||position}`:'旧構成（編集して配信枠を選択）';})():s.placements.map(p=>placementName[p]||p).join('<br>')}</td><td>${esc(s.to?.startsWith('feature/')?(state.features||[]).find(f=>'feature/'+f.id===s.to)?.title||'特集ページ':destName(s.destination))}<div class="tiny">→ ${esc(slotLink(s))}</div></td><td class="tiny">${s.start}<br>〜${s.end}</td>${section==='banner'?`<td>${s.slides?.length||1}枚・均等配信</td>`:`<td>${segmentName[s.segment]||s.segment}</td><td class="num">${s.priority}</td>`}<td class="num">${s.kind==='challenge'?`${s.participants?.toLocaleString()}/${s.challengeGoal?.toLocaleString()}人<br>+${pt(s.bonus||0)}pt`:s.reward?(s.rewardMode==='rate'?s.reward+'%':s.rewardMode==='multiplier'?'×'+s.reward:pt(s.reward)+'pt'):'—'}</td><td>${badge(k,n)}</td><td class="ops"><button class="btn sm" data-action="edit-slot" data-id="${s.id}">編集</button> <button class="btn sm" data-action="dup-slot" data-id="${s.id}">複製</button> <button class="btn sm" data-action="toggle-slot" data-id="${s.id}">${s.enabled?'停止':'再開'}</button> <button class="btn sm danger" data-action="del-slot" data-id="${s.id}">削除</button></td></tr>`;}).join('')}</tbody></table></div></section>`;}

// ===== 特集ページ =====
function featureForm(v){const o=v||{id:'',title:'',lead:'',kind:'collection',offerIds:[],start:state.date,end:'',displayLimit:20};const publication=featurePublication(o);return `<form class="grid" id="feature-form" data-new="${v?'0':'1'}">
<label>キャンペーン ID<input name="id" value="${esc(o.id)}" ${v?'readonly':''} required></label><input type="hidden" name="kind" value="collection">
<label class="wide">掲載する特集名<input name="title" value="${esc(o.title)}" required></label>
<label class="wide">特集の紹介文<textarea name="lead" rows="3" placeholder="特集の内容やおすすめのポイントを入力">${esc(o.lead||'')}</textarea></label>
<label>掲載開始日<input type="date" name="start" value="${esc(publication.start)}"></label>
<label>掲載終了日<input type="date" name="end" value="${esc(publication.end)}"></label>
<label>掲載件数（上限）<input type="number" name="displayLimit" min="1" step="1" value="${publication.displayLimit}" required></label>
<p class="wide tiny">期間は開始日・終了日を含みます。空欄の日付は制限なし。選択した案件のうち、配信可能な案件を掲載件数の上限まで表示します。掲載期間と件数はアプリに表示しません。</p>
<input type="hidden" name="bannerImage" value="${esc(o.bannerImage||'')}"><p class="wide tiny">ページ上部の画像は「<a href="#banners">バナー&テキスト広告</a>」で編集します。</p>${v?deepLinkField('feature/'+o.id):'<p class="wide tiny">作成後にディープリンクをコピーできます。</p>'}
${offerPicker(offersOf(state),o.offerIds)}<div class="actions"><button class="btn primary" type="submit">${v?'更新':'作成'}</button><button class="btn" type="button" data-action="cancel-feature">閉じる</button><span class="err" role="alert">${esc(formError)}</span></div></form>`;}

function featuresPage(){const list=state.features||[];const usedBy=id=>state.slots.filter(x=>x.to===`feature/${id}`).map(x=>x.name);return `<section class="panel"><h2>キャンペーンページ ${badge('new')}</h2><p class="desc">1つのキャンペーンに、1件以上のアフィリエイト案件をまとめたキャンペーンページです。特集名・紹介文・掲載期間・掲載件数を設定し、案件名で探して選択してください。画像は「バナー&テキスト広告」で管理します。</p><div class="toolbar"><span class="grow"></span><button class="btn primary" data-action="new-feature">＋ キャンペーンを作成</button></div>${editingFeature!==null?`<div class="panel" style="background:#FAFCFB">${featureForm(editingFeature||null)}</div>`:''}<div class="tbl"><table><thead><tr><th>ID／ディープリンク</th><th>掲載する特集名</th><th>掲載期間・件数</th><th>選択した案件</th><th>使用している枠</th><th>操作</th></tr></thead><tbody>${list.map(f=>`<tr><td><code>feature/${f.id}</code><div class="tiny"><a href="../mock-app/#feature/${f.id}" target="_blank">アプリで開く ↗</a></div></td><td><b>${esc(f.title)}</b></td><td class="tiny">${esc(featurePublication(f).start||'制限なし')} 〜 ${esc(featurePublication(f).end||'制限なし')}<br>最大 ${featurePublication(f).displayLimit}件</td><td class="tiny">${f.offerIds.map(id=>esc(offersOf(state).find(o=>o.id===id)?.name||id)).join('、')}</td><td class="tiny">${usedBy(f.id).map(esc).join('<br>')||'—'}</td><td class="ops"><button class="btn sm" data-action="edit-feature" data-id="${f.id}">編集</button> <button class="btn sm danger" data-action="del-feature" data-id="${f.id}">削除</button></td></tr>`).join('')||'<tr><td colspan="6" class="tiny">特集はありません</td></tr>'}</tbody></table></div></section>`;}


// ===== チンチロ =====
function tableRows(name,table){return `<div class="tbl"><table data-table="${name}"><thead><tr><th>役 ID（固定）</th><th>表示名（固定）・条件</th><th class="num">ウェイト</th><th class="num">倍率</th><th class="num">固定pt</th></tr></thead><tbody>${table.map(x=>`<tr><td><code>${esc(x.id)}</code></td><td><b>${esc(x.label)}</b><div class="tiny">${CHINCHIRO_ROLES.find(r=>r.id===x.id).condition}</div></td><td class="num"><input aria-label="${x.label}のウェイト" type="number" name="${name}-weight" value="${x.weight}" min="0" step="1" style="width:80px"></td><td class="num">${x.id==='miss'?'<span>0</span><input type="hidden" name="'+name+'-mult" value="0">':`<input aria-label="${x.label}の倍率" type="number" name="${name}-mult" value="${x.mult}" min="0" step="0.1" style="width:80px">`}</td><td class="num">${x.id==='miss'?'<span>0pt</span><input type="hidden" name="'+name+'-pt" value="0">':`<input aria-label="${x.label}の固定pt" type="number" name="${name}-pt" value="${x.pt??''}" min="0" step="1" style="width:90px" placeholder="空=倍率">`}</td></tr>`).join('')}</tbody></table></div>`;}
function chinchiroPage(){ensureChinchiro(state);const cfg=state.chinchiro;const st=chinchiroStatus(state);const sum=t=>t.reduce((a,x)=>a+x.weight,0);return `<section class="panel"><h2>チンチロ（日次抽選） ${badge('new')}</h2><p class="desc">アプリ右上のチンチロ入口。今日の残り回数を表示し、<b>振る前に動画リワード視聴</b>→サイコロ（目表示）→3つ同じ目は大当たり、2つだけ同じ目は当たり、すべて違う目はハズレ（0pt）。役ID・表示名は固定です。固定ptを入力するとその値を付与し、空欄の場合は基準pt × 倍率になります。デイリーミッションの「受け取る」も動画視聴後。残高そのものの倍増ではない。初期ユーザー（persona=new、または登録から earlyDays 日以内）は earlyTable。確率・倍率・日次回数はここでコントロール。</p>
<form class="grid" id="chinchiro-form">
<label>表示<select name="enabled"><option value="1" ${cfg.enabled?'selected':''}>有効</option><option value="0" ${!cfg.enabled?'selected':''}>停止</option></select></label>
<label>1日の回数上限<input type="number" name="dailyLimit" min="0" max="20" value="${cfg.dailyLimit}"></label>
<label>初期ユーザー期間（日）<input type="number" name="earlyDays" min="0" max="90" value="${cfg.earlyDays}"></label>
<label>基準ポイント（×倍率）<input type="number" name="baseReward" min="0" max="99999" value="${cfg.baseReward}"></label>
<div class="wide"><h3>通常テーブル（ウェイト合計 ${sum(cfg.normalTable)}）</h3>${tableRows('normal',cfg.normalTable)}</div>
<div class="wide"><h3>初期テーブル（ウェイト合計 ${sum(cfg.earlyTable)}）・当たりやすめ</h3>${tableRows('early',cfg.earlyTable)}</div>
<div class="actions"><button class="btn primary" type="submit">保存してアプリに反映</button><span class="err">${esc(formError)}</span></div>
</form>
<div class="preview" style="margin-top:16px"><h4>デモ利用者のいま</h4>
<p class="tiny">右上表示：${st.visible?`残り <b>${st.remaining}</b> / ${st.dailyLimit} 回${st.early?'（初期応援モード）':''}`:'非表示（ゲスト or 停止）'}　使用済み ${st.used} 回　累計ロール ${state.user.chinchiroRolls||0} 回</p>
</div>
<div class="note">ギャンブル演出は強いが、付与はボーナスのみ。景表法・射幸心・原資は要確認。</div></section>`;}

// ===== 案件画面設定 =====
const listSelect=v=>`<select name="g-list"><option value="">（なし・ナビ用）</option>${(state.nacs?.lists||[]).map(l=>`<option value="${l.code}" ${v===l.code?'selected':''}>${l.code}</option>`).join('')}</select>`;
function menuCategoryCell(g){const current=menuCategoryOf(g);return `<td><select name="g-menu-category" aria-label="メニューカテゴリ">${Object.entries(menuCategories).map(([id,name])=>`<option value="${id}" ${current===id?'selected':''}>${name}</option>`).join('')}</select></td>`;}
function menuContentSelect(kind,selected){const options=Object.entries(menuContentOptions(state,kind));return `<select name="g-category" aria-label="表示する内容" required>${options.length?options.map(([id,name])=>`<option value="${id}" ${id===selected?'selected':''}>${esc(name)}</option>`).join(''):'<option value="">キャンペーンページを先に作成してください</option>'}</select>`;}
function settingForm(code,st){const o=st||{id:'ss-'+Date.now().toString(36),applyAt:state.date+'T00:00',memo:'',groups:[{id:'g-'+Date.now().toString(36),name:'',category:code==='home_tabs'?'daily':'すべて',icon:'gift',unit:'jpy',order:1,tags:true}]};const cats=code==='home_tabs'?['daily','steps','challenge','game','shopping','survey','chat','credit']:['すべて','買い物','旅行','ゲーム','アプリ','金融','challenges','surveys','mycases'];const icons=['cart','plane','game','phone','yen','gift','spark','bag','survey','walk','wallet','calendar','chat'];
 return `<form class="grid ${code==='home_tabs'?'top-menu-form':''}" id="setting-form" data-code="${code}" data-id="${o.id}"><label>適用開始日時<input type="datetime-local" name="applyAt" value="${o.applyAt}"></label><label class="wide">メモ<input name="memo" value="${esc(o.memo)}"></label>
<div class="wide"><h3>${code==='home_tabs'?'表示するメニュー':'案件グループ'}</h3><div class="tbl"><table id="group-rows"><thead><tr><th>表示名（改行は \\n）</th>${code==='home_tabs'?'<th>メニューカテゴリ</th>':''}<th>表示する内容</th><th>案件一覧コード（NACS）</th><th>アイコン</th><th>表示単位</th><th>表示順</th><th>タグ表示</th><th></th></tr></thead><tbody>${o.groups.map((g,i)=>`<tr data-gid="${g.id}"><td><input name="g-name" value="${esc(g.name)}"></td>${code==='home_tabs'?menuCategoryCell(g):''}<td>${code==='home_tabs'?menuContentSelect(menuCategoryOf(g),g.category):`<select name="g-category">${cats.map(c=>`<option value="${c}" ${g.category===c?'selected':''}>${code==='home_tabs'?(tabName[c]||c).replace('ホーム：',''):c}</option>`).join('')}</select>`}</td><td>${listSelect(g.listCode)}</td><td><select name="g-icon">${icons.map(c=>`<option ${g.icon===c?'selected':''}>${c}</option>`).join('')}</select></td><td><select name="g-unit"><option value="jpy" ${g.unit==='jpy'?'selected':''}>円</option><option value="point" ${g.unit==='point'?'selected':''}>pt</option></select></td><td><input type="number" name="g-order" value="${g.order}" style="width:60px"></td><td><input type="checkbox" name="g-tags" ${g.tags?'checked':''}></td><td><button class="btn sm danger" type="button" data-action="del-group-row">削除</button></td></tr>`).join('')}</tbody></table></div><button class="btn sm" type="button" data-action="add-group-row">＋ メニュー／グループを追加</button></div>
<div class="actions"><button class="btn primary" type="submit">${st?'更新':'作成'}（適用開始日時が現在以前なら即時反映）</button><button class="btn" type="button" data-action="cancel-setting">閉じる</button><span class="err">${esc(formError)}</span></div></form>`;}
function topMenuPage(){screenCode='home_tabs';return screensPage();}
function screensPage(){const top=route()==='top-menu';const codes=Object.keys(state.screens);if(!state.screens[screenCode])screenCode=codes[0];const scr=state.screens[screenCode];const active=activeScreenSetting(state,screenCode);const now=state.date+'T23:59';const stateOf=x=>x.id===active?.id?['on','適用中']:x.applyAt>now?['warn','予約中']:['off','過去'];
 return `<section class="panel"><h2>${top?'TOP画面上部のメニュー':'案件グループ設定'}</h2><p class="desc">${top?'買い物・ゲーム・アンケートなど、TOP画面上部のメニューを管理します。メニューカテゴリを選び、そのカテゴリに対応する表示内容・表示名・アイコン・順序を設定し、行の追加・削除で表示するメニューを変更できます。':'オトク内の案件グループ設定を管理します。'}</p>${top?'':`<div class="tabs">${codes.filter(c=>c!=='home_tabs').map(c=>`<button data-action="screen-code" data-code="${c}">${c}</button>`).join('')}</div>`}
<p class="tiny">メモ：${esc(scr.memo)}　適用中：${active?`${active.applyAt.replace('T',' ')}（${active.groups.length}グループ）`:'なし（0 件が返る）'}</p>
<div class="toolbar"><span class="grow"></span><button class="btn primary" data-action="new-setting">＋ 設定を作成（予約可）</button></div>
${editingSetting!==null?`<div class="panel" style="background:#FAFCFB">${settingForm(screenCode,editingSetting||null)}</div>`:''}
<div class="tbl"><table><thead><tr><th>適用開始日時</th><th>状態</th><th>メモ</th><th>グループ</th><th>操作</th></tr></thead><tbody>${scr.settings.slice().sort((a,b)=>b.applyAt.localeCompare(a.applyAt)).map(x=>{const [k,n]=stateOf(x);return `<tr class="${k==='off'?'dim':''}"><td>${x.applyAt.replace('T',' ')}</td><td>${badge(k,n)}</td><td>${esc(x.memo)}</td><td class="tiny">${x.groups.slice().sort((a,b)=>a.order-b.order).map(g=>`${esc(g.name)}（${g.listCode?`<code>${g.listCode}</code>`:g.category}・${g.unit==='jpy'?'円':'pt'}）`).join('、')}</td><td class="ops"><button class="btn sm" data-action="edit-setting" data-id="${x.id}">編集</button> <button class="btn sm danger" data-action="del-setting" data-id="${x.id}">削除</button></td></tr>`;}).join('')||'<tr><td colspan="5" class="tiny">設定がありません</td></tr>'}</tbody></table></div><div class="note spec">spec：適用中の設定を削除すると直前の過去の設定に戻る。案件の並び順は NACS の掲出順で、タメルコ側で並べ替えない。案件一覧コードとその掲出順は NACS モック（<a href="../mock-nacs/#lists" target="_blank">案件一覧コード ↗</a>）で管理する。</div></section>`;}

// ===== 付与設定 =====
function pointsPage(){const rows=Object.entries(POINT_KEYS);const pend=state.reservations.filter(r=>!r.applied);const done=state.reservations.filter(r=>r.applied).slice().reverse();
 return `<section class="panel"><h2>付与設定（歩数・動画） ${badge('spec')} <span class="tiny">spec: admin/point-master.md</span></h2><p class="desc">動画リワードと歩数マイルストーン達成の「1 回の獲得で付与するポイント」「1 日の達成可能回数」を、成人・未成年の区分ごとに予約で変更する。適用日時以降の達成に新しい値が使われ、アプリの表示は次の取得で変わる。現在適用中の値そのものは変更せず、新しい予約（即時適用を含む）で置き換える。</p>
<div class="tbl"><table><thead><tr><th>設定</th><th class="num">成人（AppLovin MAX）</th><th class="num">未成年（AdMob）</th><th>備考</th></tr></thead><tbody>${rows.map(([k,d])=>`<tr><td>${d.label} ${k.startsWith('step')&&['stepGoal','stepMax'].includes(k)?badge('new'):''}</td><td class="num">${pt(state.limits[k])} ${d.unit}</td><td class="num">${['stepGoal','stepMax'].includes(k)?'<span class="tiny">共通</span>':pt(state.limitsMinor[k]??state.limits[k])+' '+d.unit}</td><td class="tiny">${k==='videoLimit'?'残り回数＝上限−当日の達成回数':k==='stepGoal'?'spec ではマイルストーン間隔・上限数の運用機能が未作成（要確認）':k==='stepMax'?'目標歩数 = 間隔 × 上限数。現在 '+(state.limits.stepMax/state.limits.stepGoal)+' 回':'付与予定は開始日時の時点の設定と照合して確定'}</td></tr>`).join('')}</tbody></table></div>
<h3>予約を作成</h3><form class="grid" id="reserve-form"><label>設定<select name="key">${rows.map(([k,d])=>`<option value="${k}">${d.label}</option>`).join('')}</select></label><label>年齢区分<select name="age"><option value="adult">成人</option><option value="minor">未成年</option></select></label><label>新しい値（整数）<input type="number" name="value" required></label><label>適用日時（未指定なら即時）<input type="datetime-local" name="applyAt"></label><div class="actions"><button class="btn primary" type="submit">予約する</button><span class="err">${esc(formError)}</span></div></form>
<h3>未適用の予約（同じ設定・年齢区分に 1 件まで）</h3><div class="tbl"><table><thead><tr><th>設定</th><th>年齢区分</th><th class="num">値</th><th>適用日時</th><th>操作</th></tr></thead><tbody>${pend.map(r=>`<tr><td>${POINT_KEYS[r.key].label}</td><td>${r.age==='minor'?'未成年':'成人'}</td><td class="num">${pt(r.value)} ${POINT_KEYS[r.key].unit}</td><td>${r.applyAt.replace('T',' ')}</td><td class="ops"><button class="btn sm danger" data-action="del-reservation" data-id="${r.id}">削除</button></td></tr>`).join('')||'<tr><td colspan="5" class="tiny">未適用の予約はありません</td></tr>'}</tbody></table></div>
<h3>適用履歴</h3><div class="tbl"><table><thead><tr><th>設定</th><th>年齢区分</th><th class="num">値</th><th>適用日時</th><th>適用日</th></tr></thead><tbody>${done.map(r=>`<tr class="dim"><td>${POINT_KEYS[r.key].label}</td><td>${r.age==='minor'?'未成年':'成人'}</td><td class="num">${pt(r.value)} ${POINT_KEYS[r.key].unit}</td><td>${r.applyAt.replace('T',' ')}</td><td>${r.appliedAt}</td></tr>`).join('')||'<tr><td colspan="5" class="tiny">履歴はありません</td></tr>'}</tbody></table></div><div class="note spec">spec：予約の作成・更新・削除には管理者ロールが必要。適用済みの値は更新・削除できない。日次の最大獲得ポイント（ポイント × 回数）が機能ごとの 1 日あたり付与上限を超える予約は拒否（上限の運用仕様は未作成のため、モックでは検証しない）。</div></section>`;}

// ===== デイリーミッション報酬 =====
function missionEditorRow(m){const fixed=isFixedMission(m);return `<tr data-task-id="${m.id}" data-task-type="${m.type}"><td><b>${fixed?'基本項目':m.type==='VIEW_OFFER'?'案件詳細閲覧':'既存の追加項目'}</b></td><td><label>タイトル<input name="title" value="${esc(m.title)}" maxlength="80"  required></label><label>説明<input name="sub" value="${esc(m.sub)}" maxlength="140"  required></label>${m.type==='VIEW_OFFER'?`<label>対象案件<select name="offerId" required><option value="">案件を選択</option>${offersOf(state).map(o=>`<option value="${o.id}" ${o.id===m.offerId?'selected':''}>${esc(o.category)} ／ ${esc(o.name)}${o.active===false?'（停止中）':''}</option>`).join('')}</select></label><label>遷移先リンク<input name="to" value="${esc(m.to|| (m.offerId?'offer/'+m.offerId:''))}" placeholder="offer/travel" required></label><small>対象案件を選ぶとリンクを自動入力します。案件詳細のURLも貼り付けられます。</small>`:''}</td><td><input type="number" name="reward" value="${m.reward}" min="1" max="99999" aria-label="${esc(m.title)} 報酬" required>pt</td><td><input type="checkbox" name="enabled" ${m.enabled?'checked':''}  aria-label="${esc(m.title)} 有効"></td><td>${m.type==='VIEW_OFFER'?'<button class="btn" type="button" data-action="remove-browse-mission">削除</button>':'—'}</td></tr>`;}
function missionsPage(){const enabled=state.missionDef.filter(m=>m.enabled);return `<section class="panel"><h2>デイリーミッション設定</h2><p class="desc">全員共通の設定です。アプリ起動・歩数・動画視聴もタイトル・説明・報酬・有効／無効を編集できます。案件詳細閲覧ミッションを追加できます。追加・削除と有効／無効で個数を調整します。</p><p class="tiny">案件の詳細ページを開くと達成します。ポイント付与は従来どおり「受け取る」の操作後です。進捗は毎日リセットされ、設定変更で受け取り済みの報酬が再付与されることはありません。</p><form id="mission-config-form" data-revision="${state.missionConfigRevision||0}"><div class="toolbar"><b data-mission-summary>有効 ${enabled.length}件 ／ 報酬合計 ${enabled.reduce((a,m)=>a+m.reward,0)}pt</b><span>1日上限 ${state.limits.missionDailyCap}pt</span></div><div class="tbl"><table><thead><tr><th>区分</th><th>内容</th><th>報酬</th><th>有効</th><th>操作</th></tr></thead><tbody id="mission-editor-rows">${state.missionDef.map(missionEditorRow).join('')}</tbody></table></div><div class="toolbar"><button class="btn" type="button" data-action="add-browse-mission">＋ 案件詳細閲覧ミッションを追加</button></div><div class="actions"><button class="btn primary" type="submit">全員共通の設定として保存</button><span class="err" role="alert"></span></div></form></section>`;}
function refreshMissionSummary(){const f=document.querySelector('#mission-config-form');if(!f)return;const rows=[...f.querySelectorAll('[data-task-id]')].filter(r=>r.querySelector('[name=enabled]').checked);f.querySelector('[data-mission-summary]').textContent=`有効 ${rows.length}件 ／ 報酬合計 ${rows.reduce((sum,r)=>sum+Number(r.querySelector('[name=reward]').value),0)}pt`;f.dataset.dirty='1';}
// ===== アンケート還元率 =====
function surveyPage(){const R=state.limits.surveyRate;const names={monitor:'モニタ情報取得',screening:'スクリーニング',main:'本調査'};return `<section class="panel"><h2>アンケートのユーザー還元率 ${badge('spec')} <span class="tiny">spec: admin/survey-redemption-rate.md</span></h2><p class="desc">種別ごとの還元率。表示は取得時点、付与は回答完了時点の率で「報酬額（円）× 率 ÷ 100 × 100 pt」を四捨五入して換算する。spec では適用開始日時つきの設定を積み上げる（モックでは即時反映）。</p>
<div class="tbl"><table><thead><tr><th>種別</th><th class="num">還元率</th><th>換算例</th><th></th></tr></thead><tbody>${Object.entries(names).map(([k,n])=>{const ex=surveys.find(q=>q.type===k);return `<tr><td>${n}</td><td class="num"><span class="inline-edit"><input type="number" min="0" max="100" value="${R[k]}" data-rate="${k}"> %</span></td><td class="tiny">${ex?`${esc(ex.title)}：${ex.rewardYen}円 → ${pt(surveyReward(state,ex))}pt`:'100円 → '+pt(Math.round(100*R[k]/100*100))+'pt'}</td><td><button class="btn sm" data-action="save-rate" data-id="${k}">保存</button></td></tr>`;}).join('')}</tbody></table></div><div class="note spec">spec：種別に設定が 1 件もない場合、一覧は 100% で表示し、付与は保留して運用者が確認する。</div></section>`;}

// ===== 審査・交換上限 =====
function reviewPage(){const pend=state.user.pendings;const cap=L(state).exchangeDailyCap;const used=state.exchangeUsedToday;return `<section class="panel"><h2>付与予定の審査 ${badge('spec')} <span class="tiny">spec: admin/point-grant-review.md / jobs/point-auto-review.md</span></h2><p class="desc">付与予定（準備中）のうち、自動判定の対象（歩数・動画・デイリーミッション・アンケート）はジョブが確定し、案件（定額・定率）は運用者の有人審査で確定する。詰まった付与予定は手動で確定・取り消しできる。取り消しはユーザーに通知しない。</p>
<div class="toolbar"><button class="btn primary" data-action="run-auto">ポイント自動判定を実行（${pend.filter(x=>x.review==='auto').length}件）</button><button class="btn" data-action="approve-all-manual">有人審査を一括承認（${pend.filter(x=>x.review==='manual').length}件）</button></div>
<div class="tbl"><table><thead><tr><th>登録日</th><th>タイトル</th><th>説明</th><th>カテゴリ</th><th class="num">pt</th><th>確定経路</th><th>操作</th></tr></thead><tbody>${pend.slice().reverse().map(p=>`<tr><td>${p.date}</td><td>${esc(p.title)}</td><td class="tiny">${esc(p.desc)}</td><td><code>${p.category}</code></td><td class="num">${pt(p.amount)}</td><td>${p.review==='manual'?badge('warn','有人審査'):badge('on','自動判定')}</td><td class="ops"><button class="btn sm" data-action="approve-pending" data-id="${p.id}">承認</button> <button class="btn sm danger" data-action="reject-pending" data-id="${p.id}">却下</button></td></tr>`).join('')||'<tr><td colspan="7" class="tiny">審査待ちはありません</td></tr>'}</tbody></table></div></section>
<section class="panel"><h2>日次交換総額上限 ${badge('spec')} <span class="tiny">spec: admin/dotmoney-exchange-cap.md</span></h2><p class="desc">サービス全体で 1 日（JST）に交換できるポイントの総量。到達後はその日の全ユーザーの交換が成立しない。未設定は上限 0 と同じ扱い。</p><div class="tiny">本日の利用 ${pt(used)} / ${pt(cap)} pt（${Math.round(used/cap*100)}%）</div><div class="meter ${used>=cap?'over':''}"><i style="width:${Math.min(100,used/cap*100)}%"></i></div><form class="grid" id="cap-form"><label>上限（pt）<input type="number" name="cap" value="${cap}" min="0"></label><div class="actions"><button class="btn primary" type="submit">保存</button><span class="err">${esc(formError)}</span></div></form></section>`;}

// ===== 成果・解禁 =====
function casesPage(){const st={challenging:'挑戦中',judging:'判定中',approved:'承認',rejected:'否認'};return `<section class="panel"><h2>案件の成果（NACS からの通知の再現） ${badge('ext')}</h2><p class="desc">成果の発生・承認・否認は NACS が正で、タメルコの運用者は変更できない。ここでは NACS からの通知を再現して、マイ案件の成果ステータスと付与予定の登録（承認 → 有人審査待ち）を確認する。成果の発生・通知の停止・再送などは <a href="../mock-nacs/#conversions" target="_blank">NACS モック ↗</a> で操作できる。</p>
<div class="tbl"><table><thead><tr><th>案件</th><th>成果 ID</th><th>ステータス</th><th>日時</th><th class="num">報酬</th><th>SUR 段階</th><th>操作</th></tr></thead><tbody>${state.user.cases.slice().reverse().map(c=>{const o=offersOf(state).find(x=>x.id===c.offerId);const open=['challenging','judging'].includes(c.status);return `<tr class="${open?'':'dim'}"><td>${esc(c.name)}</td><td class="tiny">${c.id.slice(0,8)}</td><td>${badge(c.status==='approved'?'on':c.status==='rejected'?'danger':'warn',st[c.status])}</td><td class="tiny">${c.date}</td><td class="num">${c.rewardMode==='rate'?c.reward+'%':pt(c.reward)+'pt'}</td><td>${o?.sur?`${c.paidStages}/${o.sur.length}`:'—'}</td><td class="ops">${open?`<button class="btn sm" data-action="approve-case" data-id="${c.offerId}">承認${o?.sur?'（1 段階）':''}</button> <button class="btn sm danger" data-action="reject-case" data-id="${c.offerId}">否認</button>`:''}</td></tr>`;}).join('')||'<tr><td colspan="7" class="tiny">成果はありません。アプリで案件に「チャレンジ」すると発生します</td></tr>'}</tbody></table></div></section>
<section class="panel"><h2>インストール案件の解禁 ${badge('spec')} <span class="tiny">spec: admin/install-affiliate-unlock.md</span></h2><p class="desc">同じ日に動画リワードの視聴成立を 5 件記録したユーザーは自動で解禁される。運用者は個別に解禁・再ロックできる。解禁は一覧の絞り込みにだけ効き、詳細の直接表示は妨げない。</p><p>デモ利用者：${state.user.installUnlocked?badge('on','解禁済み'):badge('off','未解禁')} <button class="btn sm" data-action="toggle-install">${state.user.installUnlocked?'再ロックする':'解禁する'}</button></p></section>
<section class="panel"><h2>デモ利用者の状態</h2><p class="tiny">確認日 ${state.date}／利用者区分 ${state.persona}／歩数連携 ${state.stepLink}／SMS 本人確認 ${state.user.sms?'済み':'未'}／本日の動画 ${day(state).video}回・歩数マイルストーン ${day(state).stepsClaimed}回。利用者側の切り替えはアプリモックの「デモ設定」で行う。</p></section>`;}

// ===== 実績 =====
function metricsPage(){const m=state.metrics;const byStatus=['challenging','judging','approved','rejected'].map(k=>[k,state.user.cases.filter(c=>c.status===k).length]);return `<section class="panel"><h2>実績 ${badge('new')}</h2><p class="desc">運用枠ごとの表示（imp）・タップ（tap）・成果（cv）、案件の成果ステータス、アンケートの開始・完了。現行仕様では行動ログ（lydia-log-constants）と Braze 側の計測に分かれており、運用画面での集計は新規。CV は承認成果を数え、開始クリックと混同しない。</p><div class="toolbar"><span class="grow"></span><button class="btn" data-action="csv">CSV を保存</button></div>
<div class="two"><div><h3>運用枠</h3><div class="tbl"><table><thead><tr><th>枠</th><th class="num">imp</th><th class="num">tap</th><th class="num">cv</th><th class="num">tap率</th></tr></thead><tbody>${state.slots.map(s=>{const x=m[s.id]||{imp:0,tap:0,cv:0};return `<tr><td>${esc(s.name)}</td><td class="num">${x.imp}</td><td class="num">${x.tap}</td><td class="num">${x.cv}</td><td class="num">${x.imp?Math.round(x.tap/x.imp*100)+'%':'—'}</td></tr>`;}).join('')}</tbody></table></div></div>
<div><h3>案件の成果ステータス</h3><div class="tbl"><table><tbody>${byStatus.map(([k,n])=>`<tr><td>${({challenging:'挑戦中',judging:'判定中',approved:'承認',rejected:'否認'})[k]}</td><td class="num">${n}</td></tr>`).join('')}</tbody></table></div><h3>アンケート</h3><div class="tbl"><table><tbody><tr><td>回答開始</td><td class="num">${state.surveyStarts.length}</td></tr><tr><td>回答完了</td><td class="num">${state.surveyCompletions.length}</td></tr><tr><td>完了率</td><td class="num">${state.surveyStarts.length?Math.round(state.surveyCompletions.length/state.surveyStarts.length*100)+'%':'—'}</td></tr></tbody></table></div><h3>チャレンジボーナス</h3><div class="tbl"><table><tbody>${challengeSlots(state).map(c=>`<tr><td>${esc(c.name)}</td><td class="num">${c.participants.toLocaleString()} / ${c.challengeGoal.toLocaleString()}人 ${challengeAchieved(c)?badge('on','達成'):''}</td></tr>`).join('')}</tbody></table></div></div></div></section>`;}
function logsPage(){return `<section class="panel"><h2>変更ログ</h2><p class="desc">管理画面の変更系操作を、実行日時・操作者・操作・内容で記録する（spec：変更系 API へのアクセスは操作ログとして記録。設定単位の操作者名は記録されない）。</p><div class="tbl"><table><thead><tr><th>日時</th><th>操作者</th><th>操作</th><th>内容</th></tr></thead><tbody>${state.logs.map(l=>`<tr><td class="tiny">${l.at.slice(0,19).replace('T',' ')}</td><td>${esc(l.actor)}</td><td>${esc(l.label)}</td><td class="log-details" title="${esc(l.details)}">${esc(l.details)}</td></tr>`).join('')||'<tr><td colspan="4" class="tiny">ログはありません</td></tr>'}</tbody></table></div></section>`;}

// ===== 描画 =====
const pages={dashboard:['ダッシュボード',dashboard],'top-menu':['TOP画面上部のメニュー',topMenuPage],challenges:['チャレンジボーナス',slotsPage],banners:['バナー&テキスト広告',slotsPage],campaigns:['キャンペーンページ',featuresPage],'text-ads':['オトク内テキスト広告',slotsPage],chinchiro:['チンチロ',chinchiroPage],screens:['案件画面設定',screensPage],points:['付与設定',pointsPage],missions:['デイリーミッション設定',missionsPage],survey:['アンケート還元率',surveyPage],review:['審査・交換上限',reviewPage],cases:['成果・解禁',casesPage],metrics:['実績',metricsPage],logs:['変更ログ',logsPage]};
function render(){const [title,fn]=pages[route()]||pages.dashboard;document.title=`${title} | タメルコ 管理画面モック`;root.innerHTML=shell(title,fn());}
function updated(msg){save();render();if(msg)toast(msg);}
function showModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="btn sm" data-action="close">閉じる</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function readSlotForm(f,preview=false){if(f.dataset.section==='banner')return readCarouselForm(state,f,state.slots.find(x=>x.id===f.dataset.id)||editingSlot||{},preview);const fd=new FormData(f),old=state.slots.find(x=>x.id===f.dataset.id)||editingSlot||{},section=f.dataset.section;const resolved=section==='banner'?resolveBannerLink(state,fd.get('to'),location.href):null;return {...old,id:f.dataset.id,name:fd.get('name').trim(),kind:section==='text'?'ticker':section==='challenge'?'challenge':fd.get('kind'),destination:resolved?(old.kind==='challenge'?old.destination:resolved.destination):fd.get('destination'),placements:fd.getAll('placements'),enabled:fd.get('enabled')==='1',start:fd.get('start'),end:fd.get('end'),segment:fd.get('segment'),priority:Number(fd.get('priority')),title:section==='text'?fd.get('title').trim():old.title||fd.get('name').trim(),text:old.text||'',bannerImage:section==='text'?'':fd.get('bannerImage')??old.bannerImage??'',rewardMode:old.rewardMode||'flat',reward:old.reward||0,to:resolved?resolved.to:section==='challenge'?old.to:fd.get('to').trim(),tab:fd.get('tab')||old.tab,position:fd.get('position')||old.position||'top',...(section==='challenge'?{challengeGoal:Number(fd.get('challengeGoal')),participants:Number(fd.get('participants')),bonus:Number(fd.get('bonus'))}:{})};}

function readSettingForm(f){const fd=new FormData(f);const rows=[...f.querySelectorAll('#group-rows tbody tr')];return {id:f.dataset.id,applyAt:fd.get('applyAt'),memo:fd.get('memo').trim(),groups:rows.map((tr,i)=>({id:tr.dataset.gid,name:tr.querySelector('[name=g-name]').value.trim(),category:tr.querySelector('[name=g-category]').value,...(f.dataset.code==='home_tabs'?{menuCategory:tr.querySelector('[name=g-menu-category]').value}:{}),listCode:tr.querySelector('[name=g-list]')?.value||undefined,icon:tr.querySelector('[name=g-icon]').value,unit:tr.querySelector('[name=g-unit]').value,order:Number(tr.querySelector('[name=g-order]').value)||i+1,tags:tr.querySelector('[name=g-tags]').checked}))};}
function csv(){const rows=[['slot','name','kind','imp','tap','cv'],...state.slots.map(s=>{const x=state.metrics[s.id]||{imp:0,tap:0,cv:0};return [s.id,s.name,s.kind,x.imp,x.tap,x.cv];})];const text=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');const u=URL.createObjectURL(new Blob(['﻿'+text],{type:'text/csv'}));const a=document.createElement('a');a.href=u;a.download=`tameruko-metrics-${state.date}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;formError='';
 try{switch(a){
 case'edit-campaign-banner':editingCampaignBanner=id;editingSlot=null;render();break;
 case'close-campaign-banner':editingCampaignBanner=null;render();break;
 case'move-challenge':moveChallenge(state,id,Number(el.dataset.dir));updated('チャレンジボーナスの並び順を保存しました。');break;
 case'add-browse-mission':document.querySelector('#mission-editor-rows').insertAdjacentHTML('beforeend',missionEditorRow({id:'browse-'+crypto.randomUUID().slice(0,8),type:'VIEW_OFFER',title:'案件の詳細ページを見てみよう',sub:'対象案件の詳細ページを開いたらクリア',offerId:'',reward:100,enabled:true,extra:true}));refreshMissionSummary();break;
 case'remove-browse-mission':el.closest('tr').remove();refreshMissionSummary();break;
 case'reload':load();render();toast('アプリの状態を読み込みました。');break;
 case'close':modal.close();break;
 // 運用枠
 case'new-slot':editingSlot=null;editingSlot=undefined;render();break;
 case'edit-slot':editingSlot=state.slots.find(x=>x.id===id);render();break;
 case'dup-slot':{const src=state.slots.find(x=>x.id===id);editingSlot={...src,id:'slot-'+Date.now().toString(36),name:src.name+'（複製）'};render();break;}
 case'cancel-slot':editingSlot=null;render();break;
 case'toggle-slot':{const s=state.slots.find(x=>x.id===id);s.enabled=!s.enabled;audit(state,`枠を${s.enabled?'再開':'停止'}：${s.name}`,'');updated(`${s.name} を${s.enabled?'再開':'停止'}しました。アプリの次回表示から反映されます。`);break;}
 case'del-slot':{const s=state.slots.find(x=>x.id===id);if(confirm(`「${s.name}」を削除します。元に戻せません。`)){removeSlot(state,id);updated('枠を削除しました。');}break;}
 // 特集
 case'new-feature':editingFeature=undefined;render();break;
 case'edit-feature':editingFeature=state.features.find(x=>x.id===id);render();break;
 case'cancel-feature':editingFeature=null;render();break;
 case'del-feature':{const used=state.slots.filter(x=>x.to===`feature/${id}`);if(used.length){toast(`この特集は枠「${used[0].name}」のリンク先です。先に枠のリンク先を変えてください。`);break;}if(confirm('この特集を削除します。')){removeFeature(state,id);updated('特集を削除しました。');}break;}
 // 案件画面設定
 case'screen-code':screenCode=el.dataset.code;editingSetting=null;render();break;
 case'new-screen':{const code=prompt('画面コード（アプリが FetchAffiliateGroups に渡す文字列）');if(!code)break;if(state.screens[code]){toast('同じ画面コードがあります。');break;}state.screens[code]={memo:prompt('メモ')||'',settings:[]};audit(state,`画面を作成：${code}`,'');screenCode=code;updated('画面コードを作成しました。設定を持たないため、アプリからは 0 件が返ります。');break;}
 case'new-setting':editingSetting=undefined;render();break;
 case'edit-setting':editingSetting=state.screens[screenCode].settings.find(x=>x.id===id);render();break;
 case'cancel-setting':editingSetting=null;render();break;
 case'del-setting':if(confirm('この設定を削除します。適用中の設定を削除すると直前の過去の設定に戻ります。')){deleteScreenSetting(state,screenCode,id);updated('設定を削除しました。');}break;
 case'add-group-row':{const tb=document.querySelector('#group-rows tbody');const gid='g-'+Date.now().toString(36);tb.insertAdjacentHTML('beforeend',`<tr data-gid="${gid}"><td><input name="g-name"></td>${screenCode==='home_tabs'?menuCategoryCell({category:'daily'}):''}<td><select name="g-category" aria-label="表示する内容">${(screenCode==='home_tabs'?['daily']:['すべて','買い物','旅行','ゲーム','アプリ','金融','challenges','surveys','mycases']).map(c=>`<option value="${c}">${screenCode==='home_tabs'?(tabName[c]||c).replace('ホーム：',''):c}</option>`).join('')}</select></td><td>${listSelect('')}</td><td><select name="g-icon">${['cart','plane','game','phone','yen','gift','spark','bag','survey','walk','wallet','calendar','chat'].map(c=>`<option>${c}</option>`).join('')}</select></td><td><select name="g-unit"><option value="jpy">円</option><option value="point">pt</option></select></td><td><input type="number" name="g-order" value="${tb.children.length+1}" style="width:60px"></td><td><input type="checkbox" name="g-tags" checked></td><td><button class="btn sm danger" type="button" data-action="del-group-row">削除</button></td></tr>`);break;}
 case'del-group-row':el.closest('tr').remove();break;
 // 付与設定
 case'del-reservation':deleteReservation(state,id);updated('予約を削除しました。');break;
 // ミッション
 case'save-mission':{const v=Number(document.querySelector(`input[data-mission="${id}"]`).value);setMissionReward(state,id,v);updated('報酬を変更しました。即時に反映されます。');break;}
 case'toggle-mission':{const m=state.missionDef.find(x=>x.id===id);setMissionEnabled(state,id,!m.enabled);updated(`タスクを${m.enabled?'有効':'無効'}にしました。`);break;}
 // 還元率
 case'save-rate':{const v=Number(document.querySelector(`input[data-rate="${id}"]`).value);setSurveyRate(state,id,v);updated('還元率を変更しました。一覧の表示と以降の付与に反映されます。');break;}
 // 審査
 case'run-auto':{const n=autoReview(state);updated(`ポイント自動判定を実行し、${n}件を確定しました。`);break;}
 case'approve-all-manual':{const n=manualReview(state);updated(`有人審査で${n}件を承認しました。`);break;}
 case'approve-pending':reviewPending(state,id,true);updated('承認しました。保有ポイントに移りました。');break;
 case'reject-pending':if(confirm('この付与予定を却下（取り消し）します。ユーザーには通知されません。')){reviewPending(state,id,false);updated('却下しました。');}break;
 // 成果
 case'approve-case':progressOffer(state,id);updated('NACS の成果承認を再現しました。付与予定（有人審査）に登録されます。');break;
 case'reject-case':rejectOffer(state,id);updated('NACS の成果否認を再現しました。');break;
 case'toggle-noloss':state.showNoLoss=!(state.showNoLoss!==false);audit(state,`目減りゼロ表示を${state.showNoLoss?'ON':'OFF'}`,'');updated(state.showNoLoss?'目減りゼロ表示をONにしました。':'目減りゼロ表示をOFFにしました。');break;
 case'toggle-install':state.user.installUnlocked=!state.user.installUnlocked;audit(state,`インストール案件を${state.user.installUnlocked?'解禁':'再ロック'}`,'デモ利用者');updated(state.user.installUnlocked?'解禁しました。':'再ロックしました。同日に動画を5回視聴すると再度解禁されます。');break;
 case'csv':csv();toast('CSV を保存しました。');break;
 }}catch(err){formError=err.message;render();toast(err.message);}
});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;const fid=f.getAttribute('id');formError='';const before=structuredClone(state);try{if(f.dataset.uploading)throw Error('画像の読み込み完了をお待ちください。');
 if(fid==='mission-config-form'){const tasks=[...f.querySelectorAll('[data-task-id]')].map(r=>({id:r.dataset.taskId,type:r.dataset.taskType,title:r.querySelector('[name=title]').value.trim(),sub:r.querySelector('[name=sub]').value.trim(),reward:Number(r.querySelector('[name=reward]').value),enabled:r.querySelector('[name=enabled]').checked,...(r.dataset.taskType==='VIEW_OFFER'?{offerId:r.querySelector('[name=offerId]').value,to:r.querySelector('[name=to]').value.trim(),extra:true}:{extra:state.missionDef.find(m=>m.id===r.dataset.taskId)?.extra||false})}));saveMissionConfig(state,tasks,Number(f.dataset.revision));updated('全員共通のデイリーミッション設定を保存しました。');}
 else if(fid==='campaign-banner-form'){const old=state.features.find(x=>x.id===f.dataset.id);if(!old)throw Error('キャンペーンが見つかりません。');saveFeature(state,{...old,bannerImage:new FormData(f).get('bannerImage')||''});save();editingCampaignBanner=null;render();toast('バナー画像を保存しました。');}
 else if(fid==='slot-form'){const v=readSlotForm(f);publishSlot(state,v);updated(`「${v.name}」を反映しました。アプリの次回表示から配信判定に使われます。`);editingSlot=null;render();}
 else if(fid==='feature-form'){const fd=new FormData(f);const old=(state.features||[]).find(x=>x.id===fd.get('id'))||{};const v={...old,id:fd.get('id').trim(),title:fd.get('title').trim(),lead:fd.get('lead').trim(),start:fd.get('start'),end:fd.get('end'),displayLimit:Number(fd.get('displayLimit')),kind:fd.get('kind'),offerIds:fd.getAll('offerIds'),note:old.note||'',bannerImage:fd.get('bannerImage')||''};if(f.dataset.new==='1'&&(state.features||[]).some(x=>x.id===v.id))throw Error('同じ ID の特集があります。');saveFeature(state,v);updated(`特集「${v.title}」を保存しました。`);editingFeature=null;render();}

 else if(fid==='setting-form'){const v=readSettingForm(f);saveScreenSetting(state,f.dataset.code,v);editingSetting=null;updated('案件画面設定を保存しました。');}
 else if(fid==='reserve-form'){const fd=new FormData(f);const r=reservePointSetting(state,fd.get('key'),fd.get('age'),Number(fd.get('value')),fd.get('applyAt'));updated(r.applied?'即時に適用しました。アプリの表示は次の取得で変わります。':`予約しました（適用 ${r.applyAt.replace('T',' ')}）。`);}
 else if(fid==='cap-form'){setExchangeCap(state,Number(new FormData(f).get('cap')));updated('日次交換総額上限を保存しました。');}
 else if(fid==='chinchiro-form'){const fd=new FormData(f);const readTable=name=>{const weights=fd.getAll(`${name}-weight`);const mults=fd.getAll(`${name}-mult`);const pts=fd.getAll(`${name}-pt`);return CHINCHIRO_ROLES.map(({id,label},i)=>{const row={id,label,weight:Number(weights[i]),mult:Number(mults[i])};const p=String(pts[i]??'').trim();if(p!=='')row.pt=Number(p);return row;});};
  setChinchiro(state,{enabled:fd.get('enabled')==='1',dailyLimit:Number(fd.get('dailyLimit')),earlyDays:Number(fd.get('earlyDays')),baseReward:Number(fd.get('baseReward')),normalTable:readTable('normal'),earlyTable:readTable('early')});updated('チンチロ設定を保存しました。アプリの右上・抽選に反映されます。');}
}catch(err){state=before;formError=err.name==='QuotaExceededError'?'画像の保存容量が足りません。画像を小さくして再度保存してください。':err.message;const error=f.querySelector('.err');if(error)error.textContent=formError;toast(formError);}});
document.addEventListener('change',e=>{if(e.target.id==='admin-date'){state.date=e.target.value;applyReservations(state);updated('確認日を切り替えました。予約の適用判定にも使われます。');}if(e.target.id==='slot-filter'){slotFilter=e.target.value;render();}});
window.addEventListener('hashchange',()=>{editingSlot=null;editingSetting=null;editingFeature=null;editingCampaignBanner=null;formError='';if(route()==='screens'&&screenCode==='home_tabs')screenCode='tametoku_quick';render();});
window.addEventListener('storage',e=>{if(e.key===KEY){const editing=document.querySelector('form[data-dirty="1"]');load();if(!editing)render();}});
save();render();

new MutationObserver(()=>initBannerEditor()).observe(root,{childList:true});
initBannerEditor();

document.addEventListener('input',e=>{if(e.target.closest('#mission-config-form'))refreshMissionSummary();});
document.addEventListener('change',e=>{if(e.target.closest('#mission-config-form'))refreshMissionSummary();});

document.addEventListener('change',e=>{if(e.target.name!=='g-menu-category')return;const row=e.target.closest('tr'),current=row.querySelector('[name=g-category]');const wrapper=document.createElement('div');wrapper.innerHTML=menuContentSelect(e.target.value,'');current.replaceWith(wrapper.firstElementChild);row.closest('form').dataset.dirty='1';});

document.addEventListener('change',e=>{if(e.target.matches('#mission-config-form [name=offerId]'))e.target.closest('tr').querySelector('[name=to]').value='offer/'+e.target.value;});
